#include "openref_rt595_slot_authenticator.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
typedef struct{uint8_t flash[12288];uint8_t sum;bool truncate;}fake_t;static bool rd(void*c,uint32_t a,uint8_t*d,uint32_t n){fake_t*f=c;if(f->truncate||a>sizeof(f->flash)||n>sizeof(f->flash)-a)return false;memcpy(d,&f->flash[a],n);return true;}static bool sig(void*c,const uint8_t*d,const uint8_t*k,const uint8_t*s){(void)c;return d[0]==0x4f&&k[0]==0x33&&s[0]==0x5a;}static bool hb(void*c){((fake_t*)c)->sum=0;return true;}static bool hu(void*c,const uint8_t*d,uint32_t n){while(n--)((fake_t*)c)->sum+=*d++;return true;}static bool hf(void*c,uint8_t*d){for(unsigned i=0;i<32;i++)d[i]=((fake_t*)c)->sum+i;return true;}static void w32(uint8_t*d,uint32_t v){d[0]=v;d[1]=v>>8;d[2]=v>>16;d[3]=v>>24;}
static void image(fake_t*f,uint32_t manifest,uint32_t image_base,uint32_t version){uint8_t*m=&f->flash[manifest];memset(m,0,144);m[0]=0x4f;m[1]=0x52;m[2]=0x55;m[3]=0x50;m[4]=1;m[5]=OPENREF_UPDATE_TARGET_AUDIO;w32(m+8,0x1234);w32(m+12,version);w32(m+16,2);w32(m+20,5);for(unsigned i=0;i<32;i++)m[24+i]=15+i;memset(m+56,0x22,16);memset(m+72,0x33,8);m[80]=0x5a;for(unsigned i=0;i<5;i++)f->flash[image_base+i]=i+1;}
int main(void){fake_t f={0};image(&f,4096,8192,7);openref_update_platform_t p={OPENREF_UPDATE_TARGET_AUDIO,0x1234,3,5,6,256};openref_update_crypto_t c={sig,hb,hu,hf,&f};openref_rt595_slot_authenticator_t a;openref_rt595_slot_reader_t r={rd,&f};openref_boot_slot_t slot;assert(openref_rt595_slot_authenticator_init(&a,r,&p,c,0,1024,256,4096,8192,256));assert(openref_rt595_slot_authenticate(&a,1,0,&slot)&&slot.authenticated&&slot.version==7&&a.authenticated_image_size[1]==5u);/* The immutable bootstrap has no application slot and must be able to
authenticate either bank before selecting it. */assert(openref_rt595_slot_authenticate(&a,1,OPENREF_BOOT_NO_SLOT,&slot)&&slot.authenticated&&slot.version==7);f.flash[8192]^=1;assert(!openref_rt595_slot_authenticate(&a,1,0,&slot)&&!slot.authenticated&&a.authenticated_image_size[1]==0u);image(&f,4096,8192,7);f.truncate=true;assert(!openref_rt595_slot_authenticate(&a,1,0,&slot));f.truncate=false;assert(!openref_rt595_slot_authenticate(&a,0,0,&slot));assert(!openref_rt595_slot_authenticate(&a,0,2u,&slot));assert(!openref_rt595_slot_authenticator_init(&a,r,&p,c,0,1024,256,4096,4200,256));image(&f,4096,8192,6);assert(!openref_rt595_slot_authenticate(&a,1,0,&slot));puts("openref_rt595_slot_authenticator_test: PASS");return 0;}
